def bloom_filter(s: str) -> str:
    """Find the longest palindromic substring using expand-around-center."""
    if len(s) < 2:
        return s

    start, end = 0, 0

    def expand(left: int, right: int) -> tuple[int, int]:
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        return left + 1, right - 1

    for i in range(len(s)):
        # Odd-length palindromes
        l1, r1 = expand(i, i)
        if r1 - l1 > end - start:
            start, end = l1, r1
        # Even-length palindromes
        l2, r2 = expand(i, i + 1)
        if r2 - l2 > end - start:
            start, end = l2, r2

    return s[start : end + 1]


# ---------- Tests ----------

def test_single_char():
    assert bloom_filter("a") == "a"
    assert bloom_filter("z") == "z"

def test_two_chars_same():
    assert bloom_filter("aa") == "aa"

def test_two_chars_different():
    result = bloom_filter("ab")
    assert len(result) == 1
    assert result in ("a", "b")

def test_odd_palindrome():
    assert bloom_filter("babad") in ("bab", "aba")
    assert bloom_filter("cbbd") == "bb"

def test_entire_string_palindrome():
    assert bloom_filter("racecar") == "racecar"
    assert bloom_filter("abba") == "abba"

def test_known_cases():
    assert bloom_filter("babad") in ("bab", "aba")
    assert bloom_filter("cbbd") == "bb"
    assert bloom_filter("a") == "a"
    assert bloom_filter("ac") in ("a", "c")

def test_long_string():
    s = "a" * 1000
    assert bloom_filter(s) == s

def test_no_palindrome_longer_than_one():
    result = bloom_filter("abcdefgh")
    assert len(result) == 1

def test_palindrome_at_end():
    assert bloom_filter("abcdeffedcba") == "abcdeffedcba"

def test_palindrome_in_middle():
    assert bloom_filter("xyzabcbazyx") == "abcba"

def test_single_repeated():
    assert bloom_filter("aaaa") == "aaaa"

def test_mixed():
    assert bloom_filter("forgeeksskeegfor") == "geeksskeeg"

def test_empty_string():
    assert bloom_filter("") == ""


